const crypto=require('crypto');
const input=$input.first(), headers=input.json.headers??{}, raw64=input.binary?.data?.data;
const timestamp=String(headers['x-slack-request-timestamp']??''), signature=String(headers['x-slack-signature']??''), secret=$env.SLACK_SIGNING_SECRET;
if(!raw64||!secret||!timestamp||!signature||Math.abs(Date.now()/1000-Number(timestamp))>300) throw new Error('Rejected Slack callback: missing, expired, or incomplete signature data');
const raw=Buffer.from(raw64,'base64').toString('utf8');
const expected='v0='+crypto.createHmac('sha256',secret).update(`v0:${timestamp}:${raw}`).digest('hex');
if(expected.length!==signature.length||!crypto.timingSafeEqual(Buffer.from(expected),Buffer.from(signature))) throw new Error('Rejected Slack callback: invalid signature');
const encoded=(raw.match(/(?:^|&)payload=([^&]*)/)??[])[1];
const payload=JSON.parse(encoded?decodeURIComponent(encoded.replace(/\+/g,' ')):''), button=payload.actions?.[0], value=JSON.parse(button?.value??'');
const mapped={approve_cluster:{action:'approve',decision_type:'review'},reject_cluster:{action:'reject',decision_type:'review'},split_cluster:{action:'split',decision_type:'review'},retry_investigation:{action:'retry',decision_type:'investigation'},dismiss_investigation:{action:'dismiss',decision_type:'investigation'},split_investigation:{action:'split',decision_type:'investigation'}}[button?.action_id];
const messageTs=String(payload.message?.ts??payload.container?.message_ts??''),hasTarget=mapped?.decision_type==='review'?Boolean(value.report_draft_id):Boolean(value.investigation_id);
if(!mapped||!value.cluster_id||!hasTarget||!payload.user?.id||!button.action_ts||!payload.team?.id||!payload.channel?.id||!messageTs) throw new Error('Rejected Slack callback: invalid action payload');
return [{json:{cluster_id:value.cluster_id,report_draft_id:value.report_draft_id??null,investigation_id:value.investigation_id??null,action:mapped.action,decision_type:mapped.decision_type,actor_id:payload.user.id,workspace_id:payload.team.id,channel_id:payload.channel.id,callback_id:`${payload.user.id}:${button.action_id}:${button.action_ts}`,message_ts:messageTs,message_text:String(payload.message?.text??'Root-cause review'),message_blocks:Array.isArray(payload.message?.blocks)?payload.message.blocks:[]}}];

const expectedWorkspace='REPLACE_WITH_SLACK_WORKSPACE_ID';
const expectedChannel='REPLACE_WITH_SUPPORT_TRIAGE_CHANNEL_ID';
if($json.workspace_id!==expectedWorkspace||$json.channel_id!==expectedChannel) throw new Error('Rejected Slack callback: unexpected workspace or review channel');
return $input.all();

const allowed=new Set(['delivery_queued','rejected','split','ignored_not_pending','duplicate_callback']);
if(!allowed.has($json.action_status))return[];
const labels={delivery_queued:'Approved',rejected:'Rejected',split:'Split requested',ignored_not_pending:'Already processed',duplicate_callback:'Already processed'};
const icons={delivery_queued:'✅',rejected:'❌',split:'🔀',ignored_not_pending:'ℹ️',duplicate_callback:'ℹ️'};
const blocks=($json.message_blocks??[]).filter(block=>block.type!=='actions');
blocks.push({type:'context',elements:[{type:'mrkdwn',text:`${icons[$json.action_status]} *${labels[$json.action_status]}* by <@${$json.actor_id}>`} ]});
return[{json:{...$json,slack_body:{channel:$json.channel_id,ts:$json.message_ts,text:`Root-cause review — ${labels[$json.action_status]}`,blocks}}}];
